   293	static int note_append(size_t *off, const char *fmt, ...)
   294	{
   295	  va_list ap;
   296	  int n;
   297	  size_t cap;
   298	
   299	  if (g_note == NULL || g_note_cap < 2)
   300	    {
   301	      return -1;
   302	    }
   303	
   304	  cap = g_note_cap;
   305	  if (*off >= cap - 1)
   306	    {
   307	      return 0;
   308	    }
   309	
   310	  va_start(ap, fmt);
   311	  n = vsnprintf(g_note + *off, cap - *off, fmt, ap);
   312	  va_end(ap);
   313	  if (n < 0)
   314	    {
   315	      return -1;
   316	    }
   317	
   318	  if ((size_t)n >= cap - *off)
   319	    {
   320	      *off = cap - 1;
   321	    }
   322	  else
   323	    {
   324	      *off += (size_t)n;
   325	    }
   326	
   327	  return 0;
   328	}
