   466	/**
   467	 * @brief 把指定任务栈顶 48 个字（192 B）写进 note。
   468	 *
   469	 * 为什么需要：WDT 停喂的现场只留下 `wait=0x… wd=0`（无超时 sem_wait）和
   470	 * `nxsem_wait_slow` 里的 pc/lr —— **上层调用者在栈上**。没有这段栈切片，
   471	 * 就只能知道"卡在某把锁"，不能知道"从哪一行开始等"。
   472	 *
   473	 * 放在任务表之前：note 容量只有 16 KB，任务表会把尾部截掉（现场那份就截在
   474	 * pid=21）。栈切片按 sp 往上取，覆盖 setjmp 保存区与上层返回地址。
   475	 */
   476	static void note_stack_slice(size_t *off, FAR const char *name)
   477	{
   478	  struct note_find_s f;
   479	  FAR const uint32_t *r;
   480	  uintptr_t lo;
   481	  uintptr_t hi;
   482	  uintptr_t sp;
   483	  size_t size;
   484	  int i;
   485	
   486	  /* 任务表用完之后 tcb 的引用就释放了：把"查表 + 取栈 + 读内存"整段放进
   487	   * sched_lock 里，避免任务在这一小段窗口里退出/被重建（本板单核，代价极小）。 */
   488	  sched_lock();
   489	
   490	  f.name = name;
   491	  f.tcb  = NULL;
   492	  nxsched_foreach(note_find_task, &f);
   493	
   494	  if (f.tcb == NULL)
   495	    {
   496	      sched_unlock();
   497	      note_append(off, "stack[%s] no-tcb\n", name);
   498	      return;
   499	    }
   500	
   501	  r = f.tcb->xcp.regs;
   502	  if (r == NULL)
   503	    {
   504	      sched_unlock();
   505	      note_append(off, "stack[%s] no-regs\n", name);
   506	      return;
   507	    }
   508	
   509	  sp = (uintptr_t)r[REG_SP];
   510	  lo = (uintptr_t)f.tcb->stack_base_ptr;
   511	  size = f.tcb->adj_stack_size;
   512	
   513	  /* 本 port 的可用栈区间 = [stack_base_ptr, stack_base_ptr + adj_stack_size)：
   514	   * arm_createstack.c:161 把 stack_base_ptr 直接设为 stack_alloc_ptr（**下界**），
   515	   * adj_stack_size 是向下对齐后的实际大小。曾经把 stack_base_ptr 当上界用，
   516	   * 会把正常栈判成 BAD、让这段取证整体失效（Codex 审查 P1）。
   517	   * 另外补齐：非零/防溢出/字对齐/剩余长度，全部满足才读。 */
   518	  hi = lo + (uintptr_t)size;
   519	
   520	  if (lo == 0 || size == 0 || hi <= lo ||
   521	      sp < lo || (sp & 3u) != 0 ||
   522	      sp > hi || (hi - sp) < (uintptr_t)(48 * 4))
   523	    {
   524	      sched_unlock();
   525	      note_append(off, "stack[%s] sp=%08lx lo=%08lx size=%lu BAD\n",
   526	                  name, (unsigned long)sp, (unsigned long)lo,
   527	                  (unsigned long)size);
   528	      return;
   529	    }
   530	
   531	  note_append(off, "stack[%s] sp=%08lx lo=%08lx hi=%08lx\n",
   532	              name, (unsigned long)sp, (unsigned long)lo, (unsigned long)hi);
   533	
   534	  for (i = 0; i + 8 <= 48; i += 8)
   535	    {
   536	      FAR const uint32_t *p = (FAR const uint32_t *)(sp + (uintptr_t)(i * 4));
   537	
   538	      note_append(off, " %08lx %08lx %08lx %08lx %08lx %08lx %08lx %08lx\n",
   539	                  (unsigned long)p[0], (unsigned long)p[1],
   540	                  (unsigned long)p[2], (unsigned long)p[3],
   541	                  (unsigned long)p[4], (unsigned long)p[5],
   542	                  (unsigned long)p[6], (unsigned long)p[7]);
   543	    }
   544	
   545	  sched_unlock();
   546	}
